// src/App.js - Updated upload function with duplicate check

// Update the uploadResume function
const uploadResume = async (file) => {
  if (!file) {
    alert('Please select a file first');
    return;
  }

  // Check for duplicate filenames
  const existingFile = resumes.find(r => r.filename === file.name);
  if (existingFile) {
    alert(`File "${file.name}" is already uploaded!`);
    // Reset file input
    document.getElementById('file-upload').value = '';
    setSelectedFile(null);
    return;
  }

  const formData = new FormData();
  formData.append('file', file);

  setLoading(true);
  try {
    const response = await axios.post('/upload-resume/', formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });

    // Add the resume data to the list
    const newResume = {
      id: response.data.resume_id || Date.now().toString(),
      name: response.data.data?.name || 'Unnamed Candidate',
      skills: response.data.data?.skills || [],
      experience: response.data.data?.experience || '',
      education: response.data.data?.education || '',
      filename: file.name,
      match_score: null,
      justification: null,
      matched_skills: [],
      missing_skills: []
    };

    setResumes([...resumes, newResume]);
    alert(`✅ "${file.name}" uploaded and parsed successfully!`);
    setSelectedFile(null);
    // Reset file input
    document.getElementById('file-upload').value = '';
  } catch (error) {
    console.error('Upload error:', error);
    alert('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
  } finally {
    setLoading(false);
  }
};
// In the return section of App.js, update the Upload Resume section:

<div className="section">
  <h2>📄 Upload Resume(s)</h2>
  <div className="upload-area">
    <input
      type="file"
      accept=".pdf,.docx"
      onChange={handleFileChange}
      className="file-input"
      id="file-upload"
      multiple  // Add this for multiple files
    />
    <label htmlFor="file-upload" className="file-label">
      {selectedFile ? `${selectedFile.length} file(s) selected` : 'Choose PDF or DOCX files (multiple allowed)'}
    </label>
    <button 
      onClick={handleUpload}
      className="upload-btn"
      disabled={loading || !selectedFile}
    >
      {loading ? 'Uploading...' : 'Upload All Resumes'}
    </button>
    {selectedFile && selectedFile.length > 0 && (
      <div className="selected-files">
        <strong>Selected files:</strong>
        <ul>
          {Array.from(selectedFile).map((file, index) => (
            <li key={index}>{file.name}</li>
          ))}
        </ul>
      </div>
    )}
  </div>
</div>
// Update the handleUpload function for multiple files
const handleUpload = () => {
  if (!selectedFile || selectedFile.length === 0) {
    alert('Please select at least one file');
    return;
  }

  // Upload each file
  const uploadPromises = [];
  for (let file of selectedFile) {
    uploadPromises.push(uploadResume(file));
  }

  // Wait for all uploads to complete
  Promise.all(uploadPromises).then(() => {
    setSelectedFile(null);
    document.getElementById('file-upload').value = '';
  });
};
// Add this function to App.js
const deleteResume = async (resumeId) => {
  if (window.confirm('Are you sure you want to delete this resume?')) {
    try {
      // Try to delete from backend
      await axios.delete(`/resume/${resumeId}`);
      // Remove from frontend
      setResumes(resumes.filter(r => r.id !== resumeId));
      alert('Resume deleted successfully!');
    } catch (error) {
      console.error('Delete error:', error);
      // Even if backend fails, remove from frontend
      setResumes(resumes.filter(r => r.id !== resumeId));
      alert('Resume removed from list');
    }
  }
};
